 1	`timescale 1ns/1ps
 2	module tb;
 3	    reg clk = 0, rst_n = 1, din = 0;
 4	    wire dout;
 5	    integer errors = 0;
 6	
 7	    debouncer #(.N(4)) dut (.clk(clk), .rst_n(rst_n), .din(din), .dout(dout));
 8	    always #5 clk = ~clk;
 9	    initial begin #100000 $display("ERROR: watchdog timeout"); $finish; end
10	
11	    task expect_dout(input v);
12	        if (dout !== v) begin
13	            $display("FAIL: t=%0t dout=%b expected=%b", $time, dout, v);
14	            errors = errors + 1;
15	        end
16	    endtask
17	
18	    initial begin
19	        #1 rst_n = 0;
20	        #11 rst_n = 1;
21	        @(negedge clk);
22	        expect_dout(0);
23	        // short glitch must be filtered
24	        din = 1;
25	        repeat (2) @(negedge clk);
26	        din = 0;
27	        repeat (10) @(negedge clk);
28	        expect_dout(0);
29	        // stable high propagates
30	        din = 1;
31	        repeat (10) @(negedge clk);
32	        expect_dout(1);
33	        // stable low propagates
34	        din = 0;
35	        repeat (10) @(negedge clk);
36	        expect_dout(0);
37	        if (errors == 0) $display("TEST PASSED");
38	        else $display("TEST FAILED: %0d errors", errors);
39	        $finish;
40	    end
41	endmodule

